type TOrder = {
  id: string;
  amount: number;
  currency: "USD" | "EUR";
};

// Register a TypeScript type with Xalor
xalor.register<"ORDER", TOrder>();

// Or register using a runtime object shape
const order = {
  id: "ord_7aB91XQz",
  amount: 249.99,
  currency: "EUR"
} as const;

xalor.register<"ORDER">();

const payload = {
  id: "ord_7aB91XQz",
  amount: 249.99,
  currency: "USD"
};

// Validate incoming payloads using your registered type
xalor.parse<"ORDER">(payload);

// Or generate type-safe guards for runtime validation
const guard = xalor.guard<"ORDER">();

if (guard(payload)) {
  // ✅ Valid ORDER payload
} else {
  // ❌ Invalid ORDER payload
}

const rawUser = {
  id: "usr_91Xk2",
  username: "dev_bren",
  email: "bren@example.com",
  saltToken: "****"
};

// Remove sensitive fields before sending to client
const safeUser = transformXalor<"User", "omit">({
  mode: "omit",
  data: rawUser,
  keys: ["passwordHash", "saltToken"]
});

// Keep only what the UI needs
const publicUser = transformXalor<"User", "pick">({
  mode: "pick",
  data: safeUser,
  keys: ["id", "username", "email"]
});
